using System.ComponentModel.DataAnnotations;

namespace mediconyx_api.Models;

/// <summary>
/// One row per billed day for an admission. Generated by BedBillingService when the
/// user calls POST /api/ipd/admissions/{id}/generate-bill (or scheduled daily).
/// Idempotent: a (AdmissionId, ChargeDate) pair is unique so re-running the generator
/// will not double-bill a day.
/// </summary>
public class BedCharge
{
    public int Id { get; set; }
    public int TenantId { get; set; }

    public int AdmissionId { get; set; }
    public Admission Admission { get; set; } = null!;

    public int BedId { get; set; }
    public Bed Bed { get; set; } = null!;

    /// <summary>The bed that was active on ChargeDate (handles transfers within an admission).</summary>
    public int BedIdOnDay { get; set; }

    /// <summary>UTC date the charge is for. One charge per admission per day, regardless of bed changes.</summary>
    public DateTime ChargeDate { get; set; }

    /// <summary>The rate (BDT) used to compute Amount. Stored so historical charges don't shift if rates change.</summary>
    public decimal DailyRate { get; set; }

    public decimal Amount { get; set; }

    [StringLength(200)]
    public string? Description { get; set; }  // e.g. "ICU bed - Ward 3 - Bed B-101 - 2026-07-20"

    public int CreatedByUserId { get; set; }
    public DateTime CreatedAt { get; set; } = DateTime.UtcNow;
}
